// Pseudo per-tenant rate limiter sketch
class TenantLimiter {
  constructor() {
    this.store = new Map();
  }
  acquire(tenantId) {
    let bucket = this.store.get(tenantId);
    if (!bucket) {
      bucket = new TokenBucket(tenantId, 100, 1); // rate, burst
      this.store.set(tenantId, bucket);
    }
    if (!bucket.tryConsume()) {
      throw new Error("TooManyRequests");
    }
    return true;
  }
}
```

